_sage_const_4p5 = RealNumber('4.5'); _sage_const_1 = Integer(1); _sage_const_3 = Integer(3); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_50 = Integer(50); _sage_const_5 = Integer(5); _sage_const_51 = Integer(51); _sage_const_10 = Integer(10); _sage_const_100p0 = RealNumber('100.0'); _sage_const_2001 = Integer(2001); _sage_const_0p0 = RealNumber('0.0'); _sage_const_1en6 = RealNumber('1e-6'); _sage_const_0p25 = RealNumber('0.25'); _sage_const_0p5 = RealNumber('0.5'); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_43 = Integer(43); _sage_const_4 = Integer(4); _sage_const_60 = Integer(60)#!/usr/bin/env sage
